InvokeScript:
$reportDir = Join-Path $env:USERPROFILE 'Desktop\MSP-Reports'
if (-not (Test-Path $reportDir)) { New-Item -ItemType Directory -Path $reportDir -Force | Out-Null }
$stamp = Get-Date -Format 'yyyyMMdd-HHmmss'
$since = (Get-Date).AddHours(-24)
foreach ($log in @('System','Application')) {
  $events = Get-WinEvent -FilterHashtable @{ LogName = $log; Level = 1,2; StartTime = $since } -ErrorAction SilentlyContinue
  $out = Join-Path $reportDir "events-$log-$stamp.csv"
  if ($events) {
    $events | Select-Object TimeCreated, Id, LevelDisplayName, ProviderName, Message | Export-Csv -Path $out -NoTypeInformation
    Write-Host "Exported $($events.Count) $log events to $out"
  } else {
    Write-Host "No critical $log events in last 24 hours"
  }
}

$targets = @('8.8.8.8','1.1.1.1','google.com')
$gw = (Get-NetRoute -DestinationPrefix '0.0.0.0/0' -ErrorAction SilentlyContinue | Select-Object -First 1).NextHop
if ($gw) { $targets = @($gw) + $targets }
foreach ($t in $targets) {
  $result = Test-Connection -ComputerName $t -Count 2 -Quiet
  $status = if ($result) { 'OK' } else { 'FAIL' }
  Write-Host "[$status] $t"
}
Write-Host "DNS test: $(Resolve-DnsName google.com -ErrorAction SilentlyContinue | Select-Object -First 1 -ExpandProperty IPAddress)"

$paths = @($env:TEMP, "$env:WINDIR\Temp", "$env:WINDIR\Prefetch")
$cutoff = (Get-Date).AddDays(-7)
$total = 0
foreach ($p in $paths) {
  if (-not (Test-Path $p)) { continue }
  Get-ChildItem $p -Recurse -Force -ErrorAction SilentlyContinue | Where-Object { -not $_.PSIsContainer -and $_.LastWriteTime -lt $cutoff } | ForEach-Object {
    try { $total += $_.Length; Remove-Item $_.FullName -Force -ErrorAction Stop } catch {}
  }
}
Write-Host "Cleaned $([math]::Round($total/1MB,2)) MB of temp files"

Get-Volume | Where-Object DriveLetter -and DriveType -eq 'Fixed' | ForEach-Object {
  Write-Host "Optimizing drive $($_.DriveLetter):..."
  Optimize-Volume -DriveLetter $_.DriveLetter -ReTrim -Verbose
}
Write-Host 'Drive optimization complete'

if (Get-Module -ListAvailable PSWindowsUpdate) {
  Get-WindowsUpdate -IsInstalled:$false -ErrorAction SilentlyContinue | Select-Object Title, Size, IsDownloaded | Format-Table -AutoSize | Out-String | Write-Host
} else {
  Write-Host 'PSWindowsUpdate module not installed. Checking via COM...'
  $session = New-Object -ComObject Microsoft.Update.Session
  $searcher = $session.CreateUpdateSearcher()
  $result = $searcher.Search('IsInstalled=0')
  Write-Host "Pending updates: $($result.Updates.Count)"
  foreach ($u in $result.Updates) { Write-Host "  - $($u.Title)" }
}

$admins = Get-LocalGroupMember -Group 'Administrators' -ErrorAction SilentlyContinue
if ($admins) {
  $admins | Select-Object Name, ObjectClass, PrincipalSource | Format-Table -AutoSize | Out-String | Write-Host
} else {
  net localgroup Administrators
}

$issues = @()
$warnings = @()
Write-Host '=== LENET Spec Recommendation Check ==='
Write-Host 'Reference: LENET - TECHNO STACK - V3.0'
Write-Host ''

# Storage
Write-Host '--- Storage (SSD required since 2021) ---'
try {
  $disks = Get-PhysicalDisk -ErrorAction Stop
  foreach ($d in $disks) {
    $model = $d.FriendlyName
    $media = $d.MediaType
    $status = 'OK'
    if ($media -eq 'HDD') { $status = 'BAD - HDD is a performance bottleneck'; $issues += "HDD detected: $model" }
    elseif ($media -eq 'Unspecified' -or $media -eq 'Unknown') {
      if ($model -match 'SSD|NVMe|Solid') { $status = 'OK (model suggests SSD)' }
      elseif ($model -match 'ST[0-9]|WDC WD|Hitachi|TOSHIBA.*DT|HGST') { $status = 'BAD - Model suggests HDD'; $issues += "Possible HDD: $model" }
      else { $status = 'CHECK - Verify in CWA Storage tile'; $warnings += "Media type '$media' for $model - confirm in CWA" }
    }
    else { $status = 'OK' }
    Write-Host "  [$status] $model ($media)"
  }
} catch {
  Get-CimInstance Win32_DiskDrive | ForEach-Object {
    $m = $_.Model
    if ($m -match 'SSD|NVMe') { Write-Host "  [OK] $m" } else { Write-Host "  [CHECK] $m - verify SSD in CWA"; $warnings += $m }
  }
}

# RAM
Write-Host ''
Write-Host '--- RAM ---'
$ramGb = [math]::Round((Get-CimInstance Win32_ComputerSystem).TotalPhysicalMemory / 1GB, 1)
if ($ramGb -lt 8) { Write-Host "  [BAD] ${ramGb} GB (< 8 GB minimum)"; $issues += "RAM ${ramGb} GB below 8 GB minimum" }
elseif ($ramGb -le 16) { Write-Host "  [OK] ${ramGb} GB (>= 8 GB, good for standard users)" }
else { Write-Host "  [VERY GOOD] ${ramGb} GB (> 16 GB)" }

# CPU
Write-Host ''
Write-Host '--- CPU ---'
$cpu = (Get-CimInstance Win32_Processor | Select-Object -First 1)
Write-Host "  CPU: $($cpu.Name)"
Write-Host '  Action: Search at https://www.cpubenchmark.net/cpu_list.php'
Write-Host '  Score < 4000 = bad | > 4000 = okay | > 5000 = very good'

# Workstation age
Write-Host ''
Write-Host '--- Workstation Age ---'
$os = Get-CimInstance Win32_OperatingSystem
$installDate = $os.InstallDate
if ($installDate) {
  $age = (New-TimeSpan -Start $installDate -End (Get-Date)).Days
  $years = [math]::Round($age / 365, 1)
  Write-Host "  OS installed: $installDate ($years years ago)"
  if ($years -lt 1) { Write-Host '  [INFO] < 1 year - warranty likely active, run troubleshooting first' }
  elseif ($years -ge 4) { Write-Host '  [WARN] > 4 years - recommend replacement (2021+ spec)'; $warnings += 'Workstation older than 4 years' }
  else { Write-Host '  [INFO] 1-3 years - consult support leader if we sold this machine' }
}
$bios = Get-CimInstance Win32_BIOS
Write-Host "  Serial (warranty lookup): $($bios.SerialNumber)"
Write-Host "  Manufacturer: $((Get-CimInstance Win32_ComputerSystem).Manufacturer)"

Write-Host ''
Write-Host '=== Summary ==='
if ($issues.Count -eq 0 -and $warnings.Count -eq 0) { Write-Host 'All automated checks passed. Proceed to troubleshooting if still slow.' }
else {
  if ($issues.Count) { Write-Host 'ISSUES:'; $issues | ForEach-Object { Write-Host "  - $_" } }
  if ($warnings.Count) { Write-Host 'WARNINGS:'; $warnings | ForEach-Object { Write-Host "  - $_" } }
  Write-Host 'If below spec, speed-up attempts may have limited success.'
}

$cs = Get-CimInstance Win32_ComputerSystem
$bios = Get-CimInstance Win32_BIOS
$mfr = $cs.Manufacturer
Write-Host "Manufacturer: $mfr"
Write-Host "Model: $($cs.Model)"
Write-Host "Serial: $($bios.SerialNumber) (also in ScreenConnect > General)"
Write-Host ''
$mfrLower = $mfr.ToLower()
if ($mfrLower -match 'dell') {
  Write-Host 'Dell Support: https://www.dell.com/support/home/en-us'
  Write-Host 'Tools: Dell Command | Update, Dell SupportAssist'
} elseif ($mfrLower -match 'hp|hewlett') {
  Write-Host 'HP Support: https://support.hp.com/us-en'
  Write-Host 'Tool: HP Support Assistant'
} elseif ($mfrLower -match 'lenovo') {
  Write-Host 'Lenovo Support: https://pcsupport.lenovo.com/us/en'
  Write-Host 'Tools: Lenovo System Update, Lenovo Vantage'
} else {
  Write-Host 'Look up manufacturer support page using serial number above.'
}
Write-Host ''
Write-Host 'Run Update Check + Install. Ask senior/SOC leader before network or BIOS updates.'

Write-Host '--- Startup (Registry Run keys) ---'
$paths = @('HKLM:\Software\Microsoft\Windows\CurrentVersion\Run','HKCU:\Software\Microsoft\Windows\CurrentVersion\Run','HKLM:\Software\Microsoft\Windows\CurrentVersion\RunOnce','HKCU:\Software\Microsoft\Windows\CurrentVersion\RunOnce')
foreach ($p in $paths) {
  if (Test-Path $p) {
    Write-Host "[$p]"
    Get-ItemProperty $p -ErrorAction SilentlyContinue | ForEach-Object { $_.PSObject.Properties | Where-Object { $_.Name -notmatch '^PS' } | ForEach-Object { Write-Host "  $($_.Name) = $($_.Value)" } }
  }
}
Write-Host ''
Write-Host '--- Startup Folder ---'
@([Environment]::GetFolderPath('Startup'), "$env:ProgramData\Microsoft\Windows\Start Menu\Programs\Startup") | ForEach-Object {
  if (Test-Path $_) { Get-ChildItem $_ -ErrorAction SilentlyContinue | ForEach-Object { Write-Host "  $_" } }
}
Write-Host ''
Write-Host 'Disable via Task Manager > Startup or msconfig. Ask senior if unsure.'

$tempPath = $env:TEMP
Write-Host "Clearing: $tempPath"
$removed = 0; $skipped = 0
Get-ChildItem $tempPath -Force -ErrorAction SilentlyContinue | ForEach-Object {
  try { if ($_.PSIsContainer) { Remove-Item $_.FullName -Recurse -Force -ErrorAction Stop } else { $removed += $_.Length; Remove-Item $_.FullName -Force -ErrorAction Stop } } catch { $skipped++ }
}
Write-Host "Removed ~$([math]::Round($removed/1MB,1)) MB. Skipped $skipped locked items (OK to skip)."

Write-Host '--- Disk Free Space ---'
$issues = @()
Get-CimInstance Win32_LogicalDisk -Filter 'DriveType=3' | ForEach-Object {
  $freePct = if ($_.Size -gt 0) { [math]::Round(($_.FreeSpace / $_.Size) * 100, 1) } else { 0 }
  $status = if ($freePct -lt 20) { 'LOW - run disk cleanup'; $issues += $_.DeviceID } else { 'OK' }
  Write-Host "  [$status] $($_.DeviceID) ${freePct}% free ($([math]::Round($_.FreeSpace/1GB,1)) GB of $([math]::Round($_.Size/1GB,1)) GB)"
}
if ($issues.Count) { Write-Host 'Less than 20% free can cause slow startup. Run disk cleanup / WinDirStat.' }

$since = (Get-Date).AddDays(-30)
Write-Host "Updates installed since $since"
Write-Host 'Cross-check CWA: Tiles > Patching > History (Failed/In Progress)'
Write-Host ''
try {
  Get-HotFix | Where-Object { $_.InstalledOn -and $_.InstalledOn -ge $since } | Sort-Object InstalledOn -Descending | Select-Object InstalledOn, HotFixID, Description | Format-Table -AutoSize | Out-String | Write-Host
} catch {
  Write-Host 'Could not read hotfix history. Check CWA patching history manually.'
}
